// Get the user's question
const userMessage = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;

// Simple RAG: Search for relevant articles
function searchKnowledgeBase(query) {
  const queryLower = query.toLowerCase();
  const results = [];

  // Keywords mapping (English and Azerbaijani)
  const keywords = {
    'speed': ['328', 'sürət'],
    'sürət': ['328'],
    'fast': ['328'],
    'km': ['328'],
    'alcohol': ['333', '334'],
    'alkoqol': ['333', '334'],
    'drunk': ['333', '334'],
    'içki': ['333', '334'],
    'sərxoş': ['333', '334'],
    'dui': ['333', '334'],
    'license': ['332', '334'],
    'lisenziya': ['332', '334'],
    'vəsiqə': ['332'],
    'seatbelt': ['329'],
    'kəmər': ['329'],
    'belt': ['329'],
    'helmet': ['329'],
    'dəbilqə': ['329'],
    'parking': ['346', '346-1'],
    'parklanma': ['346-1'],
    'dayanma': ['346'],
    'stop': ['346'],
    'park': ['346-1'],
    'pedestrian': ['330', '338'],
    'piyada': ['330', '338'],
    'crosswalk': ['330'],
    'keçid': ['330'],
    'red light': ['327'],
    'qırmızı': ['327'],
    'svetofor': ['327'],
    'traffic light': ['327'],
    'işıq': ['327', '329'],
    'insurance': ['469'],
    'sığorta': ['469'],
    'phone': ['327'],
    'telefon': ['327'],
    'emergency': ['331'],
    'təcili': ['331'],
    'ambulance': ['331'],
    'test': ['343'],
    'müayinə': ['343'],
    'breathalyzer': ['343'],
    'exhaust': ['342'],
    'səs': ['342'],
    'loud': ['342'],
    'muffler': ['342'],
    'racing': ['511'],
    'yarış': ['511'],
    'wheelie': ['511'],
    'hooligan': ['511'],
    'xuliqan': ['511'],
    'drift': ['511'],
    'burnout': ['511'],
    'sign': ['327'],
    'nişan': ['327'],
    'railway': ['327'],
    'dəmiryol': ['327'],
    'one-way': ['327'],
    'wrong way': ['327']
  };

  // Find matching article IDs
  const matchedIds = new Set();
  for (const [keyword, ids] of Object.entries(keywords)) {
    if (queryLower.includes(keyword)) {
      ids.forEach(id => matchedIds.add(id));
    }
  }

  // If no keyword match, search in article content
  if (matchedIds.size === 0) {
    for (const article of knowledgeBase.articles) {
      const articleText = JSON.stringify(article).toLowerCase();
      const queryWords = queryLower.split(' ').filter(word => word.length > 3);
      if (queryWords.some(word => articleText.includes(word))) {
        matchedIds.add(article.id);
      }
    }
  }

  // Get matched articles
  for (const article of knowledgeBase.articles) {
    if (matchedIds.has(article.id)) {
      results.push(article);
    }
  }

  // If still no results, return common violations
  if (results.length === 0) {
    results.push(
      knowledgeBase.articles.find(a => a.id === '328'),
      knowledgeBase.articles.find(a => a.id === '346'),
      knowledgeBase.articles.find(a => a.id === '329')
    );
  }

  return results.filter(Boolean).slice(0, 3);
}

const relevantArticles = searchKnowledgeBase(userMessage);

// Format context for LLM
let context = "RELEVANT TRAFFIC FINE INFORMATION FROM AZERBAIJAN:\n\n";
for (const article of relevantArticles) {
  context += `## ${article.title}\n`;
  for (const item of article.content) {
    context += `- ${item.violation}: ${item.fine} AZN`;
    if (item.points && item.points !== 0) {
      context += `, Penalty: ${item.points}`;
    }
    context += "\n";
  }
  context += "\n";
}

return {
  json: {
    userMessage,
    chatId,
    context,
    relevantArticles
  }
};

